-- Generated by execution/homework_sql.ts from docs/homework-2026-27/final/term1-week2.json:
-- the remade Homeworks 3-6 (the teacher's version for 3-5, the remake for 6), with
-- the content review and Daniyal's notes of 9 October (Idhaar Halqi in 3 Q5,
-- Ikhfaa Haqiqi throughout 6). No real student had started any of them.
-- Loads homework 3, 4, 5, 6 for 2026/27. Review, then apply with execution/apply_migration.ts.
-- Idempotent: re-running replaces the same papers again.

do $guard$ begin
  if exists (select 1 from submissions s join homeworks h on h.id = s.homework_id
             join auth.users u on u.id = s.student_id
             where h.number in (3, 4, 5, 6) and coalesce(u.email, '') not like '%@bsms-demo.test') then
    raise exception 'a real student has work on a homework this load replaces; stop and ask';
  end if;
end $guard$;

-- Demo work on the replaced papers (answers, voice notes, attempts cascade).
delete from submissions where homework_id in (select id from homeworks where number in (3, 4, 5, 6));
-- Answers or recordings filed under ANOTHER paper but pointing at these questions:
-- the demo seed left one (Mabadi' 7 answering a Homework 6 question). Demo ones go;
-- a real one stops the load.
do $xref$ begin
  if exists (
    select 1 from answers a join submissions s on s.id = a.submission_id join auth.users u on u.id = s.student_id
     where a.question_id in (select q.id from questions q join homeworks h on h.id = q.homework_id where h.number in (3, 4, 5, 6))
       and coalesce(u.email, '') not like '%@bsms-demo.test'
    union all
    select 1 from voice_notes v join submissions s on s.id = v.submission_id join auth.users u on u.id = s.student_id
     where v.question_id in (select q.id from questions q join homeworks h on h.id = q.homework_id where h.number in (3, 4, 5, 6))
       and coalesce(u.email, '') not like '%@bsms-demo.test'
  ) then
    raise exception 'a real student has an answer pointing at a question this load replaces; stop and ask';
  end if;
end $xref$;
delete from answers a using submissions s, auth.users u
 where s.id = a.submission_id and u.id = s.student_id and u.email like '%@bsms-demo.test'
   and a.question_id in (select q.id from questions q join homeworks h on h.id = q.homework_id where h.number in (3, 4, 5, 6));
delete from voice_notes v using submissions s, auth.users u
 where s.id = v.submission_id and u.id = s.student_id and u.email like '%@bsms-demo.test'
   and v.question_id in (select q.id from questions q join homeworks h on h.id = q.homework_id where h.number in (3, 4, 5, 6));
delete from questions where homework_id in (select id from homeworks where number in (3, 4, 5, 6));

