    update questions set media = $q${"clip":{"url":"https://audio-cdn.tarteel.ai/quran/surah/husary/murattal/mp3/090.mp3","start_ms":44840,"end_ms":47732}}$q$::jsonb where position = 7 and homework_id = (select id from homeworks where number = 4);
  end if;
end $media$;

select number, title, total_marks, (select count(*) from questions q where q.homework_id = h.id) as questions
